<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {api} from '../api'
import {usePolling} from '../usePolling'
import {direction,grade,number,time} from '../format'
import type {Policy,Notice} from '../types'
import PageIntro from '../components/PageIntro.vue'
import StatCard from '../components/StatCard.vue'
import Pager from '../components/Pager.vue'
const policy=ref<Policy|null>(null); const notices=ref<Notice[]>([]); const search=ref(''); const level=ref('all'); const page=ref(0)
const {error,refresh}=usePolling(async signal=>{const [p,n]=await Promise.all([api<Policy>('/api/alerts/policy',{signal}),api<Notice[]>('/api/alerts?limit=50',{signal})]);policy.value=p;notices.value=n},5000)
const decisions=computed(()=>(policy.value?.decisions??[]).filter(d=>(level.value==='all'||grade(d.grade)===level.value)&&`${d.symbol} ${d.reason}`.toLowerCase().includes(search.value.trim().toLowerCase())).sort((a,b)=>b.grade-a.grade||(b.score??-1)-(a.score??-1)))
const paged=computed(()=>decisions.value.slice(page.value*30,(page.value+1)*30));watch([search,level],()=>{page.value=0})
const noticeStatus=(s:number)=>['Pending','Dispatching','Submitted','Failed','Indeterminate','Expired','Disabled'][s]??'Unknown'
</script>
<template><PageIntro eyebrow="SIGNAL ≠ NOTIFICATION" title="少一点打扰，多一点依据。" description="每条提醒经过数据门槛、风险过滤、竞争排名和持久化去重。"><span class="live-pill">{{time(policy?.asOf)}}</span></PageIntro><p v-if="error" class="radar-notice" role="alert">{{error}} 当前显示上次缓存。</p><p class="radar-notice">普通 A 级通知要求置信度至少 70；基础模型上限仍为 60。Submitted 仅表示 Windows 接收提交，不表示用户已经看见。</p><template v-if="policy"><div class="stats"><StatCard label="普通通知 · 今日已预留" :value="`${policy.dailyUsed} / ${policy.dailyLimit}`" :foot="`${policy.budgetDate} · 上海时间每日重置`"/><StatCard label="窗口内新标的" :value="`${policy.windowAssetsUsed} / ${policy.windowAssetLimit}`" foot="滚动窗口 · 保留竞争名额"/><StatCard label="Windows Toast" :value="policy.toastEnabled?'已启用':'已关闭'" foot="应用配置 · 实际提交见下方记录"/><StatCard label="本轮 A / S 级信号" :value="policy.decisions.filter(d=>d.grade>=3).length" foot="高分不等于通知"/></div><div class="section-heading"><h2>策略评估</h2><span class="refresh-text">{{policy.policyVersion}} · {{time(policy.asOf)}}</span></div><div class="market-panel"><div class="toolbar"><label class="search"><input v-model="search" aria-label="搜索通知评估合约" placeholder="搜索合约或拦截原因"></label><select v-model="level" aria-label="信号等级筛选"><option value="all">全部等级</option><option v-for="g in ['S','A','B','C','Unknown']" :key="g">{{g}}</option></select><span class="results">{{decisions.length}} 条</span></div><div class="table-scroll"><table><thead><tr><th>合约</th><th>方向</th><th>等级</th><th>分数</th><th>置信度</th><th>阶段</th><th>通知策略结果</th></tr></thead><tbody><tr v-for="d in paged" :key="`${d.key}:${d.symbol}`"><td>{{d.symbol}}</td><td>{{direction(d.direction)}}</td><td><span class="grade" :class="`grade-${grade(d.grade).toLowerCase()}`">{{grade(d.grade)}}</span></td><td>{{number(d.score,1)}}</td><td>{{d.confidence}}</td><td>{{d.stage}}</td><td class="decision-reason">{{d.reason}}</td></tr><tr v-if="!decisions.length"><td colspan="7" class="empty">暂无符合条件的评估。</td></tr></tbody></table></div><Pager v-model="page" :total="decisions.length">同时检查分数、置信度与独立证据家族。</Pager></div></template><div class="section-heading radar-heading"><h2>通知记录</h2><button class="text-button" @click="refresh">刷新记录</button></div><div class="market-panel table-scroll"><table><thead><tr><th>创建时间</th><th>类型</th><th>标题</th><th>状态</th><th>说明</th></tr></thead><tbody><tr v-for="n in notices" :key="n.id"><td>{{time(n.createdAt)}}</td><td>{{['普通','系统性','测试','自选关键','自选观察'][n.kind]}}</td><td class="decision-reason">{{n.title}}</td><td>{{noticeStatus(n.status)}}</td><td class="decision-reason">{{n.error??(n.status===2?'Windows 已接收，系统设置可能影响实际显示':n.body)}}</td></tr><tr v-if="!notices.length"><td colspan="5" class="empty">尚无通知记录。没有符合条件的信号时保持安静。</td></tr></tbody></table></div><details class="detail"><summary>等级和通知规则</summary><p>S：评分 ≥92、置信度 ≥80、至少 4 个家族且风险低；A：上涨 ≥82 / 下跌 ≥75、置信度 ≥70、至少 3 个家族。高分但证据不足为 B，70 分以下为 C，数据无效为 Unknown。</p><p>普通通知默认每日 5 条，30 分钟最多 2 个新标的，等待 60 秒参与竞争。同 Episode 最多两次，第二次须明显升级。关闭、失败、过期和结果未知的记录仍保留额度和去重记录。</p></details></template>
